function togglePause(){if(gameOver)return;paused=!paused;ui.pause.classList.toggle('show',paused);document.getElementById('pauseBtn').innerHTML=paused?'▶ &nbsp; RESUME':'Ⅱ &nbsp; PAUSE'}
document.getElementById('pauseBtn').addEventListener('click',togglePause);document.getElementById('dodgeBtn').addEventListener('click',blink);document.getElementById('restartBtn').addEventListener('click',restart);document.getElementById('soundBtn').addEventListener('click',e=>{sound=!sound;e.currentTarget.textContent=sound?'♫':'♪';e.currentTarget.style.color=sound?'#cfc2a5':'#766f5f';if(sound)beep(520,.08)});
function frame(now){const dt=Math.min((now-last)/1000,.034)||0;last=now;update(dt);draw();requestAnimationFrame(frame)}
spawnClock=.8;showToast('THE SHADES ARE COMING');updateUI();requestAnimationFrame(frame);
})();
